def fibonacci_iterative(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return b

print(fibonacci_iterative(10))

def is_palindrome(s):
    return s == s[::-1]

print(is_palindrome('racecar'))

